import 'package:flutter/material.dart';
import 'package:widgetbook/widgetbook.dart';
import 'package:widgetbook_annotation/widgetbook_annotation.dart' as widgetbook;

// Generated by build_runner from the @UseCase annotations in lib/stories/.
// Run: dart run build_runner build --delete-conflicting-outputs
import 'main.directories.g.dart';

void main() => runApp(const HlthWidgetbook());

@widgetbook.App()
class HlthWidgetbook extends StatelessWidget {
  const HlthWidgetbook({super.key});

  @override
  Widget build(BuildContext context) {
    return Widgetbook.material(
      directories: directories,
      addons: [
        // Real device frames matter here. A chart that reads fine at 430pt
        // falls apart on a 375pt SE, and that is exactly the kind of thing
        // the review should catch before anyone grades colour.
        DeviceFrameAddon(
          devices: [
            Devices.ios.iPhoneSE,
            Devices.ios.iPhone13,
            Devices.ios.iPhone13ProMax,
            Devices.android.samsungGalaxyS20,
          ],
          initialDevice: Devices.ios.iPhone13,
        ),
        ThemeAddon(
          themes: [
            WidgetbookTheme(name: 'Light', data: ThemeData.light()),
            WidgetbookTheme(name: 'Dark', data: ThemeData.dark()),
          ],
          themeBuilder: (context, theme, child) => Theme(
            data: theme,
            child: child,
          ),
        ),
        // Accessibility text sizes break chart labels before they break
        // anything else. Keep this visible during reviews.
        TextScaleAddon(scales: [1.0, 1.3, 2.0]),
      ],
    );
  }
}
